import * as THREE from 'three';

export const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

export const TAU = Math.PI * 2;
export function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return a + d * t;
}
export function dampAngle(a, b, lambda, dt) {
  let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return a + d * (1 - Math.exp(-lambda * dt));
}

export function seeded(seed = 1) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

let gradientMap = null;
export function getGradientMap() {
  if (gradientMap) return gradientMap;
  const steps = new Uint8Array([72, 132, 196, 240, 255]);
  gradientMap = new THREE.DataTexture(steps, steps.length, 1, THREE.RedFormat);
  gradientMap.minFilter = THREE.NearestFilter;
  gradientMap.magFilter = THREE.NearestFilter;
  gradientMap.generateMipmaps = false;
  gradientMap.needsUpdate = true;
  return gradientMap;
}

export function toon(color, opts = {}) {
  const mat = new THREE.MeshToonMaterial({
    color,
    gradientMap: getGradientMap(),
    ...opts,
  });
  return mat;
}

export function standard(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.75, metalness: 0, ...opts });
}

export function makeCanvasTexture(size, draw, { repeat = 1, srgb = true } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  draw(ctx, size);
  const tex = new THREE.CanvasTexture(canvas);
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.anisotropy = 4;
  return tex;
}

export function addOutline(mesh, scale = 1.05, color = 0x2a241c) {
  const mat = new THREE.MeshBasicMaterial({ color, side: THREE.BackSide });
  const outline = new THREE.Mesh(mesh.geometry, mat);
  outline.scale.copy(mesh.scale).multiplyScalar(scale);
  outline.position.copy(mesh.position);
  outline.rotation.copy(mesh.rotation);
  outline.renderOrder = (mesh.renderOrder || 0) - 1;
  mesh.parent.add(outline);
  return outline;
}

// Rounded leaf shape used for pauldrons, skirt panels and decoration.
export function leafShape(width = 0.5, length = 1) {
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.bezierCurveTo(width * 0.55, length * 0.18, width * 0.5, length * 0.62, 0, length);
  s.bezierCurveTo(-width * 0.5, length * 0.62, -width * 0.55, length * 0.18, 0, 0);
  return s;
}

export function leafGeometry(width = 0.5, length = 1, depth = 0.012) {
  const geo = new THREE.ExtrudeGeometry(leafShape(width, length), {
    depth,
    bevelEnabled: true,
    bevelSize: 0.008,
    bevelThickness: 0.006,
    bevelSegments: 1,
    curveSegments: 8,
  });
  geo.center();
  return geo;
}

export function radialTexture(size = 128, inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  return makeCanvasTexture(size, (ctx, s) => {
    const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.55, inner);
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
  }, { srgb: false });
}

export function softPatchTexture(size = 128) {
  return makeCanvasTexture(size, (ctx, s) => {
    const g = ctx.createRadialGradient(s / 2, s / 2, s * 0.12, s / 2, s / 2, s * 0.5);
    g.addColorStop(0, 'rgba(255,255,255,0.95)');
    g.addColorStop(0.7, 'rgba(255,255,255,0.7)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
  }, { srgb: false });
}

export function disposeGroup(group) {
  group.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m) => {
        if (m.map) m.map.dispose();
        m.dispose();
      });
    }
  });
}

export function setShadow(obj, cast = true, receive = true) {
  obj.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = cast;
      o.receiveShadow = receive;
    }
  });
}

import * as THREE from 'three';
import { makeCanvasTexture, seeded } from './utils.js';

function noise(ctx, s, colors, count, rnd, size = [1, 3]) {
  for (let i = 0; i < count; i++) {
    ctx.fillStyle = colors[Math.floor(rnd() * colors.length)];
    const r = size[0] + rnd() * (size[1] - size[0]);
    ctx.beginPath();
    ctx.ellipse(rnd() * s, rnd() * s, r, r * (0.4 + rnd()), rnd() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
}

export function makeGrassTexture(anisotropy = 4) {
  const tex = makeCanvasTexture(512, (ctx, s) => {
    const rnd = seeded(7);
    ctx.fillStyle = '#5c853f';
    ctx.fillRect(0, 0, s, s);
    // large soft tonal patches
    for (let i = 0; i < 26; i++) {
      const x = rnd() * s, y = rnd() * s, r = 40 + rnd() * 110;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      const light = rnd() > 0.5;
      g.addColorStop(0, light ? 'rgba(126,164,82,0.4)' : 'rgba(70,108,54,0.38)');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
    noise(ctx, s, ['#527a39', '#6a9448', '#7ba454', '#486d33'], 1400, rnd, [0.6, 2.4]);
    // blades
    for (let i = 0; i < 2400; i++) {
      const x = rnd() * s, y = rnd() * s, h = 2 + rnd() * 5;
      ctx.strokeStyle = ['#456c32', '#6a9347', '#83ac5d', '#557f3c'][Math.floor(rnd() * 4)];
      ctx.globalAlpha = 0.4 + rnd() * 0.4;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + (rnd() - 0.5) * 3, y - h * 0.6, x + (rnd() - 0.5) * 4, y - h);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    // tiny flowers
    const flower = ['#f4efd7', '#f2d98a', '#e7b6c6', '#d9e8f2'];
    for (let i = 0; i < 46; i++) {
      ctx.fillStyle = flower[Math.floor(rnd() * flower.length)];
      ctx.beginPath();
      ctx.arc(rnd() * s, rnd() * s, 1.2 + rnd() * 0.9, 0, Math.PI * 2);
      ctx.fill();
    }
    // gentle vignette-like variation
    const v = ctx.createLinearGradient(0, 0, s, s);
    v.addColorStop(0, 'rgba(255,255,220,0.05)');
    v.addColorStop(1, 'rgba(20,50,20,0.09)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, s, s);
  }, { repeat: 1 });
  tex.anisotropy = anisotropy;
  return tex;
}

export function makeStoneTexture(anisotropy = 4) {
  const tex = makeCanvasTexture(512, (ctx, s) => {
    const rnd = seeded(23);
    ctx.fillStyle = '#7f8274';
    ctx.fillRect(0, 0, s, s);
    const cell = 64;
    for (let gy = 0; gy < s / cell; gy++) {
      for (let gx = 0; gx < s / cell; gx++) {
        const x = gx * cell + (rnd() - 0.5) * 6;
        const y = gy * cell + (rnd() - 0.5) * 6;
        const w = cell - 6 - rnd() * 5, h = cell - 6 - rnd() * 5;
        const tone = 158 + Math.floor(rnd() * 42);
        ctx.fillStyle = `rgb(${tone},${tone + 3},${tone - 12})`;
        ctx.beginPath();
        const rr = 6 + rnd() * 5;
        ctx.roundRect(x + 3, y + 3, w, h, rr);
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,240,0.12)';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
    }
    noise(ctx, s, ['#6f7264', '#9b9e8c', '#8a8d7c', '#b1b39f'], 900, rnd, [0.5, 2.2]);
    // moss in grout
    for (let i = 0; i < 120; i++) {
      ctx.fillStyle = `rgba(${86 + rnd() * 30},${112 + rnd() * 26},${58 + rnd() * 20},0.55)`;
      ctx.beginPath();
      ctx.arc(rnd() * s, rnd() * s, 1 + rnd() * 4, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  tex.anisotropy = anisotropy;
  return tex;
}

export function makeDirtTexture(anisotropy = 4) {
  const tex = makeCanvasTexture(512, (ctx, s) => {
    const rnd = seeded(41);
    ctx.fillStyle = '#a9835a';
    ctx.fillRect(0, 0, s, s);
    noise(ctx, s, ['#98744e', '#b89367', '#8e6b46', '#c2a075'], 2000, rnd, [0.6, 3]);
    for (let i = 0; i < 240; i++) {
      ctx.fillStyle = ['#7c7a6c', '#8f8b7a', '#b9b2a0'][Math.floor(rnd() * 3)];
      ctx.beginPath();
      ctx.ellipse(rnd() * s, rnd() * s, 0.8 + rnd() * 2.2, 0.6 + rnd() * 1.6, rnd() * 3, 0, Math.PI * 2);
      ctx.fill();
    }
    // faint wheel ruts
    ctx.strokeStyle = 'rgba(110,80,50,0.18)';
    for (let i = 0; i < 4; i++) {
      ctx.lineWidth = 4 + rnd() * 8;
      ctx.beginPath();
      ctx.moveTo(0, 40 + i * 120 + rnd() * 20);
      ctx.bezierCurveTo(s * 0.3, 80 + i * 120, s * 0.7, 10 + i * 120, s, 60 + i * 120);
      ctx.stroke();
    }
  });
  tex.anisotropy = anisotropy;
  return tex;
}

export function makeDressTexture() {
  const tex = makeCanvasTexture(256, (ctx, s) => {
    const rnd = seeded(5);
    const g = ctx.createLinearGradient(0, 0, 0, s);
    g.addColorStop(0, '#6b8a35');
    g.addColorStop(1, '#54702b');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
    // leaf motifs
    for (let i = 0; i < 16; i++) {
      const x = (i % 4) * 64 + 32 + (rnd() - 0.5) * 14;
      const y = Math.floor(i / 4) * 64 + 32 + (rnd() - 0.5) * 14;
      const a = rnd() * Math.PI * 2;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(a);
      ctx.scale(0.8 + rnd() * 0.5, 0.8 + rnd() * 0.5);
      ctx.fillStyle = i % 3 === 0 ? 'rgba(40,63,21,0.55)' : 'rgba(133,163,78,0.5)';
      ctx.beginPath();
      ctx.moveTo(0, -22);
      ctx.bezierCurveTo(16, -12, 15, 12, 0, 24);
      ctx.bezierCurveTo(-15, 12, -16, -12, 0, -22);
      ctx.fill();
      ctx.strokeStyle = 'rgba(214,196,120,0.65)';
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(0, -20);
      ctx.lineTo(0, 20);
      for (let v = -14; v < 18; v += 8) {
        ctx.moveTo(0, v);
        ctx.lineTo(9, v - 5);
        ctx.moveTo(0, v);
        ctx.lineTo(-9, v - 5);
      }
      ctx.stroke();
      ctx.restore();
    }
    // subtle fabric weave
    ctx.globalAlpha = 0.08;
    for (let i = 0; i < s; i += 4) {
      ctx.fillStyle = i % 8 ? '#fff8d0' : '#20300e';
      ctx.fillRect(i, 0, 1, s);
    }
    ctx.globalAlpha = 1;
  });
  tex.repeat.set(2, 1.4);
  return tex;
}

export function makeLeatherTexture() {
  const tex = makeCanvasTexture(128, (ctx, s) => {
    const rnd = seeded(11);
    ctx.fillStyle = '#7b5736';
    ctx.fillRect(0, 0, s, s);
    noise(ctx, s, ['#6a492d', '#8a6440', '#94704a', '#5e4027'], 500, rnd, [0.8, 3.2]);
    ctx.strokeStyle = 'rgba(228,201,144,0.35)';
    ctx.setLineDash([4, 3]);
    ctx.lineWidth = 1.4;
    ctx.strokeRect(8, 8, s - 16, s - 16);
    ctx.setLineDash([]);
  });
  return tex;
}

export function makeWoodTexture() {
  const tex = makeCanvasTexture(256, (ctx, s) => {
    const rnd = seeded(17);
    ctx.fillStyle = '#8a5f3a';
    ctx.fillRect(0, 0, s, s);
    for (let p = 0; p < 4; p++) {
      const y = p * 64;
      ctx.fillStyle = p % 2 ? '#906541' : '#835935';
      ctx.fillRect(0, y + 2, s, 60);
      ctx.strokeStyle = 'rgba(60,35,18,0.45)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, y + 1);
      ctx.lineTo(s, y + 1);
      ctx.stroke();
      for (let i = 0; i < 9; i++) {
        ctx.strokeStyle = `rgba(72,44,24,${0.12 + rnd() * 0.2})`;
        ctx.lineWidth = 1 + rnd() * 1.6;
        ctx.beginPath();
        const yy = y + 8 + rnd() * 46;
        ctx.moveTo(0, yy);
        ctx.bezierCurveTo(s * 0.3, yy + 3, s * 0.7, yy - 3, s, yy + 2);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(55,35,18,0.6)';
      ctx.beginPath();
      ctx.arc(40 + rnd() * 170, y + 26 + rnd() * 16, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  tex.repeat.set(2, 2);
  return tex;
}

export function makeThatchTexture() {
  const tex = makeCanvasTexture(256, (ctx, s) => {
    const rnd = seeded(29);
    ctx.fillStyle = '#4d6a32';
    ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 90; i++) {
      ctx.strokeStyle = ['#3e5828', '#5d7d3a', '#6f9144', '#47632e'][Math.floor(rnd() * 4)];
      ctx.lineWidth = 2 + rnd() * 3;
      ctx.beginPath();
      const x = rnd() * s, y = rnd() * s;
      ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + 8, y + 16, x + 4 + rnd() * 10, y + 34);
      ctx.stroke();
    }
    for (let i = 0; i < 24; i++) {
      ctx.fillStyle = 'rgba(188,184,105,0.28)';
      ctx.beginPath();
      ctx.ellipse(rnd() * s, rnd() * s, 5 + rnd() * 12, 2 + rnd() * 4, rnd() * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  tex.repeat.set(2, 2);
  return tex;
}

export function makeBarkTexture() {
  const tex = makeCanvasTexture(256, (ctx, s) => {
    const rnd = seeded(31);
    ctx.fillStyle = '#6a4f36';
    ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 60; i++) {
      ctx.strokeStyle = `rgba(${40 + rnd() * 40},${30 + rnd() * 30},${18 + rnd() * 20},${0.3 + rnd() * 0.4})`;
      ctx.lineWidth = 1 + rnd() * 3;
      const x = rnd() * s;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.bezierCurveTo(x + 8, s * 0.3, x - 8, s * 0.7, x + 4, s);
      ctx.stroke();
    }
    for (let i = 0; i < 24; i++) {
      ctx.fillStyle = 'rgba(104,128,72,0.32)';
      ctx.beginPath();
      ctx.ellipse(rnd() * s, rnd() * s, 3 + rnd() * 7, 2 + rnd() * 4, rnd() * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  tex.repeat.set(1, 2);
  return tex;
}

export function makePetalTexture() {
  return makeCanvasTexture(64, (ctx, s) => {
    ctx.clearRect(0, 0, s, s);
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse(s / 2, s / 2, s * 0.22, s * 0.42, 0, 0, Math.PI * 2);
    ctx.fill();
  }, { srgb: false });
}

export function makeWindowTexture() {
  return makeCanvasTexture(128, (ctx, s) => {
    const g = ctx.createRadialGradient(s / 2, s / 2, 2, s / 2, s / 2, s / 2);
    g.addColorStop(0, '#ffe9a6');
    g.addColorStop(0.55, '#e8b65c');
    g.addColorStop(1, '#9c6a32');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
    ctx.strokeStyle = '#5a3a22';
    ctx.lineWidth = 8;
    ctx.strokeRect(2, 2, s - 4, s - 4);
    ctx.beginPath();
    ctx.moveTo(s / 2, 0);
    ctx.lineTo(s / 2, s);
    ctx.moveTo(0, s / 2);
    ctx.lineTo(s, s / 2);
    ctx.stroke();
  });
}

import * as THREE from 'three';
import {
  clamp, lerp, rand, seeded, smoothstep, toon, getGradientMap,
  softPatchTexture, leafGeometry, TAU,
} from './utils.js';
import {
  makeGrassTexture, makeStoneTexture, makeDirtTexture, makeWoodTexture,
  makeThatchTexture, makeBarkTexture, makeWindowTexture,
} from './textures.js';

const deg = (d) => (d * Math.PI) / 180;

function makeSignTexture(title, subtitle) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  // wooden board
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, '#a97a4c');
  g.addColorStop(0.5, '#91663d');
  g.addColorStop(1, '#7d5532');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 512, 256);
  for (let i = 0; i < 40; i++) {
    ctx.strokeStyle = `rgba(70,44,23,${0.08 + Math.random() * 0.16})`;
    ctx.lineWidth = 1 + Math.random() * 3;
    ctx.beginPath();
    ctx.moveTo(0, Math.random() * 256);
    ctx.bezierCurveTo(150, Math.random() * 256, 350, Math.random() * 256, 512, Math.random() * 256);
    ctx.stroke();
  }
  ctx.strokeStyle = '#5b3a20';
  ctx.lineWidth = 14;
  ctx.strokeRect(7, 7, 498, 242);
  ctx.strokeStyle = 'rgba(255,236,190,0.25)';
  ctx.lineWidth = 3;
  ctx.strokeRect(20, 20, 472, 216);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#f7edcb';
  ctx.shadowColor = 'rgba(40,24,10,0.6)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 3;
  ctx.font = '86px Jua, sans-serif';
  ctx.fillText(title, 256, 108);
  ctx.font = '34px "Gowun Dodum", sans-serif';
  ctx.fillStyle = '#e4d3a2';
  ctx.fillText(subtitle, 256, 186);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeWaterMaterial() {
  return new THREE.ShaderMaterial({
    transparent: false,
    toneMapped: true,
    uniforms: {
      uTime: { value: 0 },
      uA: { value: new THREE.Color('#4f8984') },
      uB: { value: new THREE.Color('#7bb8ac') },
      uC: { value: new THREE.Color('#d9efe0') },
    },
    vertexShader: /* glsl */`
      varying vec2 vUv;
      varying vec3 vWorld;
      void main() {
        vUv = uv;
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */`
      uniform float uTime;
      uniform vec3 uA;
      uniform vec3 uB;
      uniform vec3 uC;
      varying vec2 vUv;
      varying vec3 vWorld;
      void main() {
        vec2 p = vUv * 2.0 - 1.0;
        float d = length(p);
        float r1 = sin(d * 26.0 - uTime * 1.6);
        float r2 = sin(vUv.x * 24.0 + uTime * 0.9) * sin(vUv.y * 19.0 - uTime * 1.1);
        float ripple = smoothstep(0.55, 1.0, r1 * 0.4 + r2 * 0.5);
        float shimmer = pow(max(0.0, sin((vUv.x + vUv.y) * 38.0 + uTime * 2.2)), 18.0);
        vec3 col = mix(uA, uB, 0.35 + 0.4 * smoothstep(0.0, 1.0, vUv.y + r2 * 0.1));
        col = mix(col, uC, ripple * 0.16 + shimmer * 0.35);
        float edge = smoothstep(0.82, 1.0, d);
        col = mix(col, uC, edge * 0.22);
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });
}

export function createWorld(scene, renderer) {
  const anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const root = new THREE.Group();
  scene.add(root);
  const colliders = [];
  const hideSpots = [];
  const updaters = [];
  const timeUniform = { value: 0 };

  const pal = {
    grass: 0x5c853f,
    grassLight: 0x86ad5a,
    leafDark: 0x36552b,
    leafMid: 0x4f7336,
    leafLight: 0x83a94f,
    bark: 0x6b4e34,
    stone: 0x9b9d8d,
    wood: 0x8a5f3a,
    thatch: 0x4d6a32,
    cream: 0xf2e9c9,
  };

  // ---------- sky ----------
  const skyUniforms = {
    uTop: { value: new THREE.Color('#8fcab8') },
    uHorizon: { value: new THREE.Color('#f5efd0') },
    uSun: { value: new THREE.Color('#ffe0a0') },
    uSunDir: { value: new THREE.Vector3(0.5, 0.7, 0.4).normalize() },
  };
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(130, 32, 20),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: skyUniforms,
      vertexShader: /* glsl */`
        varying vec3 vDir;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vDir = normalize(wp.xyz);
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: /* glsl */`
        uniform vec3 uTop; uniform vec3 uHorizon; uniform vec3 uSun; uniform vec3 uSunDir;
        varying vec3 vDir;
        void main() {
          float h = clamp(vDir.y, 0.0, 1.0);
          vec3 col = mix(uHorizon, uTop, pow(h, 0.55));
          float sd = max(dot(normalize(vDir), normalize(uSunDir)), 0.0);
          col += uSun * pow(sd, 260.0) * 2.2;
          col += uSun * pow(sd, 8.0) * 0.16;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })
  );
  sky.frustumCulled = false;
  root.add(sky);

  // ---------- lights ----------
  const hemi = new THREE.HemisphereLight(0xe8f5d8, 0x4c5c38, 0.85);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xffe9bb, 2.5);
  sun.position.set(20, 28, 14);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -34;
  sun.shadow.camera.right = 34;
  sun.shadow.camera.top = 34;
  sun.shadow.camera.bottom = -34;
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 90;
  sun.shadow.bias = -0.0006;
  sun.shadow.normalBias = 0.035;
  scene.add(sun);
  scene.add(sun.target);
  sun.target.position.set(0, 0, 0);
  const fill = new THREE.DirectionalLight(0xa9d4d8, 0.5);
  fill.position.set(-18, 12, -16);
  scene.add(fill);

  scene.fog = new THREE.Fog(0xd8e8c8, 34, 82);

  // ---------- ground ----------
  const grassTex = makeGrassTexture(anisotropy);
  grassTex.repeat.set(22, 22);
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(160, 160, 1, 1),
    toon(0xffffff, { map: grassTex })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  root.add(ground);

  // subtle dark ring under the tree line to give the clearing depth
  const outerShade = new THREE.Mesh(
    new THREE.RingGeometry(27, 60, 64),
    new THREE.MeshBasicMaterial({ color: 0x33502b, transparent: true, opacity: 0.18, depthWrite: false })
  );
  outerShade.rotation.x = -Math.PI / 2;
  outerShade.position.y = 0.004;
  root.add(outerShade);

  const stoneTex = makeStoneTexture(anisotropy);
  stoneTex.repeat.set(4, 4);
  const dirtTex = makeDirtTexture(anisotropy);
  const woodTex = makeWoodTexture();
  const thatchTex = makeThatchTexture();
  const barkTex = makeBarkTexture();
  const windowTex = makeWindowTexture();

  // ---------- paths ----------
  const pathPolylines = [
    [[0, 28], [0, 18], [0, 9], [0, 6.3]],
    [[0, -6.3], [0, -13], [0, -22]],
    [[-5.6, 2.2], [-9, 4.8], [-12.6, 6.4]],
    [[5.6, 2.2], [9, 3.3], [13, 3.6]],
  ];
  const pathPoints = [];
  function addPath(points, width) {
    const curve = new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(p[0], 0, p[1])));
    const N = 46;
    const pos = [], uv = [], idx = [];
    const length = curve.getLength();
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const p = curve.getPoint(t);
      const tan = curve.getTangent(t).normalize();
      const nx = -tan.z, nz = tan.x;
      const wobble = 1 + Math.sin(t * 23 + width) * 0.12;
      const hw = (width / 2) * wobble;
      pos.push(p.x + nx * hw, 0.018, p.z + nz * hw);
      pos.push(p.x - nx * hw, 0.018, p.z - nz * hw);
      uv.push(0, (t * length) / 2.4);
      uv.push(1, (t * length) / 2.4);
      if (i < N) {
        const a = i * 2;
        idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const mat = toon(0xffffff, { map: dirtTex, polygonOffset: true, polygonOffsetFactor: -1 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    root.add(mesh);
    points.forEach((p, i) => {
      if (i > 0) pathPoints.push([points[i - 1], p]);
    });
  }
  pathPolylines.forEach((p, i) => addPath(p, i < 2 ? 3.1 : 2.1));

  // plaza
  const plaza = new THREE.Mesh(new THREE.CircleGeometry(6.6, 56), toon(0xffffff, { map: stoneTex }));
  plaza.rotation.x = -Math.PI / 2;
  plaza.position.y = 0.02;
  plaza.receiveShadow = true;
  root.add(plaza);
  const plazaRing = new THREE.Mesh(
    new THREE.RingGeometry(6.35, 6.9, 64),
    toon(0x8d8f7e)
  );
  plazaRing.rotation.x = -Math.PI / 2;
  plazaRing.position.y = 0.035;
  root.add(plazaRing);

  // ---------- pond ----------
  const pondPos = new THREE.Vector3(-12, 0, -4);
  const pondR = 4.3;
  const pondBank = new THREE.Mesh(
    new THREE.CircleGeometry(5.3, 48),
    toon(0x9a7e56)
  );
  pondBank.rotation.x = -Math.PI / 2;
  pondBank.position.set(pondPos.x, 0.012, pondPos.z);
  pondBank.receiveShadow = true;
  root.add(pondBank);
  const waterMat = makeWaterMaterial();
  const water = new THREE.Mesh(new THREE.CircleGeometry(pondR, 56), waterMat);
  water.rotation.x = -Math.PI / 2;
  water.position.set(pondPos.x, 0.03, pondPos.z);
  root.add(water);
  const foam = new THREE.Mesh(
    new THREE.RingGeometry(pondR - 0.16, pondR + 0.12, 56),
    new THREE.MeshBasicMaterial({ color: 0xe8f2dc, transparent: true, opacity: 0.35, depthWrite: false })
  );
  foam.rotation.x = -Math.PI / 2;
  foam.position.set(pondPos.x, 0.045, pondPos.z);
  root.add(foam);
  updaters.push((dt) => { waterMat.uniforms.uTime.value += dt; });
  colliders.push({ x: pondPos.x, z: pondPos.z, r: pondR + 0.45 });

  // ---------- instanced collections ----------
  const inc = {
    foliage: [], trunks: [], grass: [], flowerHeads: [], flowerStems: [], tufts: [],
    pebbles: [], rocks: [], moss: [], logs: [], reeds: [], lilies: [], stones: [],
    mushrooms: [], mushroomCaps: [], fencePosts: [], fenceRails: [], clouds: [],
  };
  const dummy = new THREE.Object3D();
  const col = new THREE.Color();

  function pushFoliage(x, y, z, sx, sy, sz, color, rx = 0, ry = 0, rz = 0) {
    inc.foliage.push({ x, y, z, sx, sy, sz, color, rx, ry, rz });
  }
  function addTree(x, z, scale = 1, variant = 0) {
    const h = (4.5 + Math.random() * 2.6) * scale;
    const lean = (Math.random() - 0.5) * 0.09;
    inc.trunks.push({
      x, z, y: h * 0.47, sx: 1.25 * scale, sy: h * 0.5, sz: 1.25 * scale,
      rx: lean, ry: Math.random() * TAU, rz: (Math.random() - 0.5) * 0.07,
      color: variant ? 0x7a5b3e : 0xffffff,
    });
    const crownY = h * 0.88;
    const n = 5 + Math.floor(Math.random() * 3);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU + Math.random() * 0.7;
      const r = i === 0 ? 0 : (0.7 + Math.random() * 1.5) * scale;
      const s = (1.2 + Math.random() * 0.9) * scale;
      const green = [pal.leafDark, pal.leafMid, pal.leafLight, 0x5f853f, 0x74984a][Math.floor(Math.random() * 5)];
      pushFoliage(
        x + Math.cos(a) * r,
        crownY + (Math.random() - 0.35) * 1.6 * scale + (i === 0 ? 0.5 * scale : 0),
        z + Math.sin(a) * r,
        s * (0.95 + Math.random() * 0.35), s * (0.72 + Math.random() * 0.3), s * (0.95 + Math.random() * 0.35),
        green,
        Math.random() * 0.5, Math.random() * TAU, Math.random() * 0.5
      );
    }
    // a couple of low branches
    colliders.push({ x, z, r: 0.72 * scale });
    return { x, z, h };
  }
  function addBush(x, z, s = 1, color = null) {
    const n = 3 + Math.floor(Math.random() * 3);
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU, r = Math.random() * 0.55 * s;
      pushFoliage(
        x + Math.cos(a) * r, 0.35 * s + Math.random() * 0.3 * s, z + Math.sin(a) * r,
        (0.55 + Math.random() * 0.35) * s, (0.4 + Math.random() * 0.3) * s, (0.55 + Math.random() * 0.35) * s,
        color ?? [pal.leafDark, pal.leafMid, pal.leafLight][Math.floor(Math.random() * 3)],
        0, Math.random() * TAU, 0
      );
    }
  }

  // ---------- huts ----------
  const hutLocations = [
    { x: -13.5, z: 7.5, rot: Math.atan2(13.5, -7.5), s: 1 },
    { x: 13.5, z: -9, rot: Math.atan2(-13.5, 9), s: 0.95 },
    { x: -6.5, z: -18, rot: Math.atan2(6.5, 18), s: 1.08 },
    { x: -7, z: 17.5, rot: Math.atan2(7, -17.5), s: 0.88 },
  ];
  function addHut(cfg) {
    const g = new THREE.Group();
    g.position.set(cfg.x, 0, cfg.z);
    g.rotation.y = cfg.rot;
    g.scale.setScalar(cfg.s);
    root.add(g);
    const wallMat = toon(0xffffff, { map: woodTex });
    const base = new THREE.Mesh(new THREE.CylinderGeometry(2.25, 2.4, 0.34, 12), toon(0x8b8d7b));
    base.position.y = 0.17;
    base.receiveShadow = true; base.castShadow = true;
    g.add(base);
    const wall = new THREE.Mesh(new THREE.CylinderGeometry(1.95, 2.05, 1.9, 12), wallMat);
    wall.position.y = 1.22;
    wall.castShadow = true; wall.receiveShadow = true;
    g.add(wall);
    // door
    const doorShape = new THREE.Shape();
    doorShape.moveTo(-0.42, 0);
    doorShape.lineTo(-0.42, 1.0);
    doorShape.quadraticCurveTo(0, 1.38, 0.42, 1.0);
    doorShape.lineTo(0.42, 0);
    doorShape.closePath();
    const door = new THREE.Mesh(
      new THREE.ExtrudeGeometry(doorShape, { depth: 0.09, bevelEnabled: false, curveSegments: 8 }),
      toon(0x5d4028)
    );
    door.position.set(0, 0.34, 1.94);
    g.add(door);
    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.05, 8, 6), toon(0xd8b25e));
    knob.position.set(0.24, 1.0, 2.06);
    g.add(knob);
    const lintel = new THREE.Mesh(new THREE.BoxGeometry(1.16, 0.12, 0.18), toon(0x6b4a2d));
    lintel.position.set(0, 1.81, 1.98);
    lintel.castShadow = true;
    g.add(lintel);
    // windows
    const winMat = new THREE.MeshBasicMaterial({ map: windowTex });
    [-1, 1].forEach((side) => {
      const win = new THREE.Mesh(new THREE.PlaneGeometry(0.6, 0.62), winMat);
      const a = side * 0.9;
      win.position.set(Math.sin(a) * 1.98, 1.45, Math.cos(a) * 1.98);
      win.rotation.y = a;
      g.add(win);
      const frame = new THREE.Mesh(new THREE.BoxGeometry(0.74, 0.76, 0.08), toon(0x5b4128));
      frame.position.copy(win.position);
      frame.position.multiplyScalar(0.995);
      frame.rotation.copy(win.rotation);
      g.add(frame);
      win.position.multiplyScalar(1.012);
    });
