:root {
  --ink: #24351f;
  --ink-soft: #526147;
  --ink-faint: #7c876b;
  --cream: #f8f2dd;
  --cream-2: #f0e6c9;
  --cream-3: #e7d9b4;
  --leaf: #57783a;
  --leaf-deep: #2d482b;
  --leaf-bright: #8fae5a;
  --gold: #d5a84e;
  --gold-soft: #eed49a;
  --rose: #cf8fa9;
  --panel: rgba(249, 243, 224, 0.9);
  --panel-line: rgba(78, 100, 58, 0.18);
  --shadow: 0 18px 48px rgba(22, 38, 22, 0.26);
  --font-display: 'Jua', 'Gowun Dodum', 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
  --font-body: 'Gowun Dodum', 'Apple SD Gothic Neo', 'Malgun Gothic', 'WenQuanYi Zen Hei', sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font-family: var(--font-body);
  color: var(--ink);
  background: #1d2c1e;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  -webkit-touch-callout: none;
  user-select: none;
}
button { font-family: inherit; -webkit-tap-highlight-color: transparent; }
svg { display: block; }
.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}
body.is-playing:not(.is-mobile) #scene { cursor: none; }

.world-grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(255, 247, 210, 0.05) 0%, transparent 45%, rgba(22, 40, 24, 0.3) 100%),
    linear-gradient(180deg, rgba(255, 240, 180, 0.06) 0%, transparent 26%, transparent 72%, rgba(24, 46, 28, 0.14) 100%);
}

/* ---------------- HUD ---------------- */
#hud {
  position: absolute; inset: 0; z-index: 10;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.45s ease;
  font-size: 14px;
}
.panel {
  background: var(--panel);
  border: 1px solid var(--panel-line);
  box-shadow: 0 10px 26px rgba(25, 42, 24, 0.16), inset 0 1px 0 rgba(255, 252, 240, 0.7);
  backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}
.eyebrow {
  display: block;
  font-family: var(--font-body);
  font-size: 9.5px;
  letter-spacing: 0.16em;
  color: var(--ink-faint);
  font-weight: 700;
  text-transform: uppercase;
}

.hud-top {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: max(20px, env(safe-area-inset-left));
  right: max(20px, env(safe-area-inset-right));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 14px;
}
.mission-card {
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px 10px 10px;
  border-radius: 20px;
  min-width: 260px;
}
.mission-icon {
  width: 52px; height: 52px; flex: none;
  border-radius: 15px;
  background: radial-gradient(circle at 40% 30%, #eef4d8, #dce8bf);
  display: grid; place-items: center;
  box-shadow: inset 0 0 0 1px rgba(94, 124, 62, 0.16);
}
.mission-icon svg { width: 38px; height: 38px; }
.mission-text { min-width: 80px; }
.mission-count {
  font-family: var(--font-display);
  display: flex; align-items: baseline; gap: 5px;
  line-height: 1;
  margin: 3px 0 5px;
}
.mission-count strong { font-size: 32px; font-weight: 400; color: var(--leaf-deep); letter-spacing: 0.01em; }
.mission-count span { font-size: 13px; color: var(--ink-faint); }
.pips { display: flex; gap: 5px; height: 9px; }
.pips i {
  width: 7px; height: 7px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: rgba(76, 100, 55, 0.16);
  box-shadow: inset 0 0 0 1px rgba(76, 100, 55, 0.2);
  transition: background 0.25s, transform 0.25s, box-shadow 0.25s;
}
.pips i.on { background: var(--gold); box-shadow: 0 0 0 2px rgba(213, 168, 78, 0.22), inset 0 0 0 1px rgba(255, 240, 190, 0.5); transform: rotate(-45deg) scale(1.12); }
.score-box {
  margin-left: 4px;
  padding-left: 15px;
  border-left: 1px solid rgba(74, 95, 53, 0.18);
  text-align: right;
}
.score-box strong {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 400;
  color: #7b5f2b;
  letter-spacing: 0.03em;
}

.timer-wrap { justify-self: center; display: flex; flex-direction: column; align-items: center; gap: 7px; }
.timer-pill {
  display: flex; align-items: center; gap: 10px;
  border-radius: 18px;
  padding: 8px 18px 8px 14px;
}
.sun-icon { width: 29px; height: 29px; }
.timer-text { display: flex; flex-direction: column; line-height: 1; }
.timer-text .eyebrow { font-size: 8.5px; }
.timer-text strong {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 400;
  letter-spacing: 0.06em;
  color: var(--leaf-deep);
  margin-top: 3px;
  font-variant-numeric: tabular-nums;
}
.timer-text strong.urgent { color: #a94c34; animation: urgentPulse 1s infinite; }
.timer-track {
  width: 190px; height: 4px;
  border-radius: 99px;
  background: rgba(52, 70, 42, 0.16);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(30, 45, 25, 0.15);
}
#timer-fill {
  height: 100%; width: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6f9245, #d5b461 72%, #d78c4e);
  transition: width 0.25s linear;
}

.hud-buttons { justify-self: end; display: flex; gap: 8px; pointer-events: auto; }
.icon-btn {
  width: 44px; height: 44px;
  border-radius: 14px;
  border: 1px solid var(--panel-line);
  background: var(--panel);
  color: var(--ink-soft);
  display: grid; place-items: center;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(25, 42, 24, 0.13);
  backdrop-filter: blur(10px);
  transition: transform 0.18s, background 0.18s, color 0.18s;
}
.icon-btn:hover { transform: translateY(-2px); background: #fbf6e6; color: var(--leaf-deep); }
.icon-btn svg { width: 21px; height: 21px; }
.icon-btn .ico-off { display: none; }
.icon-btn.muted .ico-on { display: none; }
.icon-btn.muted .ico-off { display: block; }

.hud-bottom {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  right: max(22px, env(safe-area-inset-right));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 18px;
}
.hint {
  justify-self: start;
  display: flex; gap: 16px;
  padding: 9px 15px;
  border-radius: 13px;
  font-size: 11px;
  color: var(--ink-soft);
}
.hint > div { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.hint span { margin-left: 3px; color: var(--ink-faint); }
kbd {
  display: inline-grid; place-items: center;
  min-width: 18px; height: 18px;
  padding: 0 4px;
  border-radius: 5px;
  background: rgba(250, 246, 232, 0.9);
  border: 1px solid rgba(74, 95, 53, 0.24);
  border-bottom-width: 2px;
  font-family: var(--font-body);
  font-size: 9.5px;
  font-weight: 700;
  color: var(--ink-soft);
}
kbd.mouse { border-radius: 50%; width: 18px; font-size: 8px; }

.detect {
  justify-self: center;
  width: 250px;
  padding: 9px 14px 10px;
  border-radius: 14px;
  transition: box-shadow 0.3s, border-color 0.3s;
}
.detect-head { display: flex; align-items: center; gap: 6px; color: var(--ink-soft); }
.detect-head svg { width: 15px; height: 15px; }
.detect-head span { font-size: 10.5px; letter-spacing: 0.1em; font-weight: 700; }
.detect-head em {
  margin-left: auto;
  font-style: normal;
  font-size: 9.5px;
  color: var(--ink-faint);
  letter-spacing: 0.04em;
}
.detect-bars { display: flex; gap: 4px; margin-top: 6px; height: 5px; }
.detect-bars i {
  flex: 1; border-radius: 99px;
  background: rgba(74, 95, 53, 0.14);
  transition: background 0.2s, box-shadow 0.2s;
}
.detect-bars i.on { background: linear-gradient(90deg, #9db56b, #d1a557); box-shadow: 0 0 6px rgba(209, 165, 87, 0.4); }
.detect.hot { border-color: rgba(190, 125, 56, 0.45); box-shadow: 0 0 0 1px rgba(213, 168, 78, 0.25), 0 10px 28px rgba(120, 80, 25, 0.18); }
.detect.hot .detect-head em { color: #a8682c; }

.focus-btn {
  justify-self: end;
  position: relative;
  width: 112px; height: 112px;
  border-radius: 50%;
  border: 1px solid rgba(74, 95, 53, 0.2);
  background:
    radial-gradient(circle at 38% 30%, rgba(255, 253, 240, 0.98), rgba(239, 231, 204, 0.95));
  color: var(--leaf-deep);
  box-shadow: 0 16px 36px rgba(25, 42, 24, 0.22), inset 0 0 0 5px rgba(255, 252, 238, 0.5);
  cursor: pointer;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 1px;
  pointer-events: auto;
  transition: transform 0.2s, background 0.3s, color 0.3s, box-shadow 0.3s;
}
.focus-btn:hover { transform: scale(1.035); }
.focus-btn:active { transform: scale(0.97); }
.focus-ring { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }
.focus-ring .ring-bg { fill: none; stroke: rgba(77, 98, 55, 0.16); stroke-width: 5; }
#focus-ring {
  fill: none;
  stroke: var(--gold);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-dasharray: 333;
  stroke-dashoffset: 0;
  filter: drop-shadow(0 0 3px rgba(213, 168, 78, 0.45));
  transition: stroke-dashoffset 0.12s linear, stroke 0.25s;
}
.focus-eye { width: 29px; height: 29px; position: relative; }
.focus-word { font-family: var(--font-display); font-size: 17px; line-height: 1.15; letter-spacing: 0.06em; }
.focus-key { font-size: 8px; letter-spacing: 0.22em; color: var(--ink-faint); font-weight: 700; }
body.focus-on .focus-btn {
  background: radial-gradient(circle at 38% 30%, #4b6b39, #2e482b);
  color: var(--cream);
  box-shadow: 0 0 0 7px rgba(213, 168, 78, 0.12), 0 18px 40px rgba(20, 40, 20, 0.34);
}
body.focus-on .focus-key { color: rgba(246, 239, 214, 0.6); }
body.focus-on #focus-ring { stroke: #ffe19a; }

.mobile-hint {
  display: none;
  position: absolute;
  left: 50%; bottom: calc(max(20px, env(safe-area-inset-bottom)) + 122px);
  transform: translateX(-50%);
  font-size: 10px;
  color: rgba(250, 244, 222, 0.9);
  text-shadow: 0 1px 4px rgba(20, 35, 20, 0.8);
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
}

#focus-overlay { position: absolute; inset: 0; z-index: 5; opacity: 0; transition: opacity 0.4s ease; pointer-events: none; }
.focus-vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 50% 52%, transparent 26%, rgba(18, 36, 24, 0.3) 62%, rgba(14, 28, 20, 0.72) 100%),
    linear-gradient(rgba(26, 49, 33, 0.14), rgba(26, 49, 33, 0.14));
}
.focus-whisper {
  position: absolute; top: 19%; left: 50%; transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 13px; letter-spacing: 0.42em; color: #ffe4a4;
  text-shadow: 0 0 18px rgba(255, 220, 130, 0.7);
  opacity: 0;
}
body.focus-on #focus-overlay { opacity: 1; }
body.focus-on .focus-whisper { animation: whisper 2.6s ease-in-out infinite; }
#dusk-overlay {
  position: absolute; inset: 0; z-index: 4; pointer-events: none;
  background: radial-gradient(ellipse at 50% 60%, transparent 20%, rgba(94, 52, 40, 0.34) 100%);
  opacity: 0; transition: opacity 1.6s ease;
}

/* ---------------- reticle & feedback ---------------- */
#reticle {
  position: absolute; z-index: 9;
  width: 50px; height: 50px;
  margin: 0; padding: 0;
  color: #fff5d4;
  transform: translate(-50%, -50%);
  pointer-events: none;
  filter: drop-shadow(0 1px 3px rgba(25, 35, 20, 0.6));
  transition: opacity 0.14s ease;
}
#reticle svg { width: 100%; height: 100%; }
#reticle.shoot { animation: reticleKick 0.26s ease-out; }
#reticle.hit { color: #ffe08a; animation: reticleHit 0.3s ease-out; }
#reticle.windup { color: #ffd677; }
#hit-marker {
  position: absolute; z-index: 11;
  width: 26px; height: 26px;
  transform: translate(-50%, -50%) rotate(45deg) scale(0.6);
  opacity: 0;
  pointer-events: none;
  background:
    linear-gradient(#fff3c4, #fff3c4) left top / 9px 2px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) left top / 2px 9px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) right top / 9px 2px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) right top / 2px 9px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) left bottom / 9px 2px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) left bottom / 2px 9px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) right bottom / 9px 2px no-repeat,
    linear-gradient(#fff3c4, #fff3c4) right bottom / 2px 9px no-repeat;
}
#hit-marker.pop { animation: hitPop 0.34s ease-out; }

#floaters { position: absolute; inset: 0; z-index: 12; pointer-events: none; overflow: hidden; }
.floater {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: 25px;
  color: #ffebaf;
  white-space: nowrap;
  text-shadow: 0 2px 0 rgba(54, 39, 13, 0.5), 0 0 16px rgba(255, 220, 130, 0.55);
  animation: floatUp 1.25s cubic-bezier(0.15, 0.7, 0.3, 1) forwards;
  will-change: transform, opacity;
}
.floater.small { font-size: 17px; color: #ecf4cf; }
.floater.big { font-size: 34px; color: #ffe188; }

#toast {
  position: absolute; z-index: 22;
  top: 106px; left: 50%;
  transform: translate(-50%, -10px);
  max-width: min(520px, 88vw);
  padding: 10px 20px;
  border-radius: 999px;
  background: rgba(36, 57, 32, 0.92);
  border: 1px solid rgba(242, 222, 166, 0.28);
  color: #f9f1d7;
  font-size: 12.5px;
  letter-spacing: 0.01em;
  text-align: center;
  box-shadow: 0 14px 34px rgba(16, 30, 16, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
  backdrop-filter: blur(8px);
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast.gold { background: rgba(120, 90, 32, 0.94); border-color: rgba(255, 231, 160, 0.42); }
#toast.warn { background: rgba(110, 52, 36, 0.94); border-color: rgba(255, 200, 160, 0.3); }

#combo-badge {
  position: absolute; z-index: 11;
  left: max(22px, env(safe-area-inset-left));
  top: 126px;
  display: flex; align-items: baseline; gap: 7px;
  padding: 7px 14px;
  border-radius: 10px;
  background: rgba(248, 240, 214, 0.92);
  border: 1px solid rgba(172, 132, 54, 0.35);
  color: #8d642a;
  box-shadow: 0 8px 20px rgba(40, 45, 20, 0.14);
  transform: rotate(-3deg);
  transition: opacity 0.25s, transform 0.25s;
}
#combo-badge.show { animation: comboPop 0.3s cubic-bezier(0.2, 1.6, 0.4, 1); }
#combo-badge span { font-size: 9.5px; letter-spacing: 0.12em; font-weight: 700; }
#combo-badge strong { font-family: var(--font-display); font-weight: 400; font-size: 20px; }

/* ---------------- joystick ---------------- */
#joystick {
  position: absolute;
  z-index: 11;
  left: max(22px, env(safe-area-inset-left));
  bottom: calc(max(22px, env(safe-area-inset-bottom)) + 6px);
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  touch-action: none;
}
.joy-base {
  position: relative;
  width: 124px; height: 124px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 32%, rgba(252, 246, 228, 0.3), rgba(32, 53, 32, 0.28));
  border: 1px solid rgba(250, 244, 222, 0.38);
  box-shadow: inset 0 0 0 9px rgba(250, 244, 222, 0.1), 0 10px 26px rgba(20, 35, 20, 0.22);
  backdrop-filter: blur(5px);
}
.joy-cross { position: absolute; inset: 26px; border-radius: 50%; border: 1px dashed rgba(250, 244, 222, 0.2); }
.joy-knob {
  position: absolute; left: 50%; top: 50%;
  width: 54px; height: 54px;
  margin: -27px 0 0 -27px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, rgba(254, 251, 238, 0.94), rgba(227, 217, 187, 0.86));
  border: 1px solid rgba(255, 252, 240, 0.6);
  box-shadow: 0 6px 16px rgba(20, 35, 20, 0.25), inset 0 0 0 4px rgba(255, 255, 248, 0.35);
  transition: transform 0.08s linear;
}
.joy-label {
  font-size: 9px; letter-spacing: 0.24em; color: rgba(250, 244, 222, 0.7);
  text-shadow: 0 1px 3px rgba(20, 35, 20, 0.6);
}

/* ---------------- title ---------------- */
.screen {
  position: absolute; inset: 0; z-index: 20;
  transition: opacity 0.55s ease, visibility 0.55s;
}
.screen.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.title-vignette {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(20, 36, 22, 0.2) 0%, transparent 34%, transparent 76%, rgba(20, 36, 22, 0.16) 100%),
    linear-gradient(180deg, rgba(22, 38, 23, 0.14) 0%, transparent 22%, transparent 76%, rgba(20, 36, 22, 0.32) 100%);
  pointer-events: none;
}
.title-panel {
  position: absolute;
  left: clamp(22px, 6.5vw, 100px);
  top: 50%;
  transform: translateY(-50%);
  width: min(474px, 43vw);
  padding: 32px 36px 28px;
  border-radius: 30px;
  background:
    radial-gradient(circle at 100% 0%, rgba(225, 210, 165, 0.55), transparent 34%),
    linear-gradient(158deg, rgba(251, 246, 230, 0.97), rgba(242, 232, 204, 0.94));
  border: 1px solid rgba(255, 253, 242, 0.72);
  box-shadow: 0 44px 96px rgba(16, 31, 18, 0.42), inset 0 0 0 1px rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  animation: panelIn 0.85s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  overflow: hidden;
}
.title-panel::after {
  content: '';
  position: absolute; inset: 10px;
  border-radius: 22px;
  border: 1px solid rgba(121, 108, 64, 0.12);
  pointer-events: none;
}
.corner-leaf { position: absolute; top: -14px; right: -12px; width: 108px; height: 108px; pointer-events: none; }
.title-eyebrow {
  display: flex; align-items: center; gap: 7px;
  font-size: 10px;
  letter-spacing: 0.18em;
  color: #6d7c55;
  font-weight: 700;
  text-transform: uppercase;
}
.title-eyebrow svg { width: 17px; height: 17px; color: #749041; }
.title-panel h1 {
  margin: 13px 0 6px;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(52px, 5.2vw, 74px);
  line-height: 0.92;
  letter-spacing: -0.02em;
  color: #26381f;
  text-shadow: 0 2px 0 rgba(255, 255, 255, 0.45);
}
.title-panel h1 em {
  position: relative;
  font-style: normal;
  color: var(--leaf);
  display: inline-block;
}
.title-panel h1 em::after {
  content: '';
  position: absolute;
  left: -2px; right: -8px; bottom: 6px;
  height: 10px;
  background: linear-gradient(90deg, rgba(143, 174, 90, 0.55), rgba(143, 174, 90, 0.05));
  border-radius: 50%;
  transform: rotate(-1.2deg);
  z-index: -1;
}
.title-en {
  font-size: 9px;
  letter-spacing: 0.34em;
  color: #8d9774;
  font-weight: 700;
  margin-bottom: 16px;
}
.story {
  margin: 0 0 18px;
  font-size: 13.5px;
  line-height: 1.82;
  color: #556348;
  word-break: keep-all;
}
.story b { color: #3c552d; }
.story-quote {
  display: block;
  margin-top: 9px;
  font-size: 12px;
  color: #729045;
  letter-spacing: 0.01em;
  border-left: 2px solid rgba(114, 144, 69, 0.4);
  padding-left: 9px;
}
.character-strip {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 12px 9px 9px;
  margin-bottom: 17px;
  border-radius: 15px;
  background: rgba(88, 116, 57, 0.08);
  border: 1px solid rgba(88, 116, 57, 0.15);
}
.avatar {
  width: 46px; height: 46px; flex: none;
  border-radius: 50%;
  overflow: hidden;
  background: #e6edcd;
  box-shadow: 0 0 0 2px rgba(255, 252, 236, 0.85), 0 3px 10px rgba(60, 80, 40, 0.16);
}
.avatar svg { width: 100%; height: 100%; }
.char-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.char-info strong { font-family: var(--font-display); font-weight: 400; font-size: 15px; color: #354c2a; letter-spacing: 0.03em; }
.char-info strong span { font-family: var(--font-body); font-size: 8.5px; letter-spacing: 0.18em; color: #8a9570; text-transform: uppercase; margin-left: 4px; }
.char-info small { font-size: 10px; color: #7b876a; }
.mission-chip {
  margin-left: auto;
  display: flex; align-items: baseline; gap: 3px;
  padding: 6px 10px;
  border-radius: 9px;
  background: linear-gradient(135deg, #eee1b8, #e4d3a4);
  border: 1px solid rgba(170, 136, 64, 0.22);
  color: #7d6128;
  white-space: nowrap;
}
.mission-chip span { font-size: 8.5px; letter-spacing: 0.05em; }
.mission-chip b { font-family: var(--font-display); font-size: 19px; font-weight: 400; }
.howto { list-style: none; margin: 0 0 19px; padding: 0; display: grid; gap: 7px; }
.howto li {
  display: flex; align-items: center; gap: 8px;
  font-size: 11.5px;
  color: #667356;
  word-break: keep-all;
}
.howto .k {
  flex: none;
  display: inline-grid; place-items: center;
  min-width: 42px; height: 20px;
  padding: 0 6px;
  border-radius: 6px;
  background: rgba(87, 120, 58, 0.12);
  color: #587636;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.howto kbd { height: 17px; font-size: 8.5px; }
.btn {
  width: 100%;
  border: none;
  border-radius: 14px;
  padding: 14px 20px;
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.04em;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center; gap: 10px;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  position: relative;
  overflow: hidden;
}
.btn svg { width: 19px; height: 19px; transition: transform 0.2s; }
.btn.primary {
  color: #fbf4dd;
  background: linear-gradient(135deg, #4e703c, #2e4a2b 70%);
  box-shadow: 0 13px 28px rgba(36, 61, 31, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.14);
}
.btn.primary::after {
  content: '';
  position: absolute; inset: 0;
