  channel: 'chromium',
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface'],
});
const page = await browser.newPage({ viewport: { width: 1050, height: 793 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__ready && window.__game);
await page.evaluate(() => window.__game.start());
await page.waitForTimeout(1200);
const result = await page.evaluate(async () => {
  const g = window.__game;
  const s = g.field.slimes.find((x) => x.state === 'hidden');
  const calls = [];
  const orig = g.field.update.bind(g.field);
  g.field.update = (...args) => {
    if (calls.length < 6) calls.push({ dt: args[0], player: { x: args[2].x, z: args[2].z }, moving: args[4] });
    return orig(...args);
  };
  g.player.pos.set(s.group.position.x + 1.1, 0, s.group.position.z);
  g.player.vel.set(0, 0, 0);
  const before = { state: g.game.state, spot: s.spot.id, slime: [s.group.position.x, s.group.position.z], player: [g.player.pos.x, g.player.pos.z] };
  const ticks = [];
  for (let i = 0; i < 10; i++) {
    await new Promise((r) => setTimeout(r, 250));
    ticks.push({ state: s.state, spot: s.spot.id, fleeClock: s.fleeClock, dist: Math.hypot(s.group.position.x - g.player.pos.x, s.group.position.z - g.player.pos.z), player: [g.player.pos.x, g.player.pos.z], gameState: g.game.state });
  }
  return { before, calls, ticks };
});
console.log(JSON.stringify(result, null, 2));
await browser.close();

