import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium, devices } = require('playwright');

const browser = await chromium.launch({
  channel: 'chromium', headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface'],
});
const context = await browser.newContext({ ...devices['iPhone 15'] });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__ready && window.__game);
await page.waitForTimeout(1200);
const titleInfo = await page.evaluate(() => ({
  coarse: matchMedia('(pointer: coarse)').matches,
  hoverNone: matchMedia('(hover: none)').matches,
  touchText: [...document.querySelectorAll('.touch-only')].map((e) => ({ text: e.textContent, display: getComputedStyle(e).display })),
  desktopText: [...document.querySelectorAll('.desktop-only')].map((e) => ({ text: e.textContent, display: getComputedStyle(e).display })),
  focusKey: getComputedStyle(document.querySelector('.focus-key')).display,
  titleMeta: getComputedStyle(document.querySelector('.title-meta')).display,
}));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-title-touch.png' });
await page.locator('#btn-start').click();
await page.waitForTimeout(2500);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-gameplay-touch.png' });
console.log(JSON.stringify(titleInfo, null, 2));
console.log('errors:', errors);
await browser.close();

